`<optgroup label="${TIER_LABEL[t]}">${
    COUNTRIES.map((c,i)=>[c,i]).filter(([c])=>c.t===t).sort((a,b)=>b[0].w-a[0].w)
      .map(([c,i])=>`<option value="${i}"${i===+UI.birthPick?' selected':''}>${c.n} · income ${fmt$(c.g)} · life exp. ${c.le}${c.war?' · at war':''}</option>`).join('')
  }</optgroup>`

